import sys

def solve(lines):
    n = int(lines[0])
    final_by_day = {}
    for i in range(1, n + 1):
        day_str, name = lines[i].split()
        day = int(day_str)
        final_by_day[day] = name
    count = {}
    max_day = {}
    for day, name in final_by_day.items():
        count[name] = count.get(name, 0) + 1
        if name not in max_day or day > max_day[name]:
            max_day[name] = day
    candidates = [name for name, c in count.items() if c >= 3]
    candidates.sort(key=lambda name: (-count[name], -max_day[name], name))
    top = candidates[:2]
    return "\n".join(top) if top else "NONE"

if __name__ == "__main__":
    lines = sys.stdin.read().splitlines()
    print(solve(lines))

