import sys
from collections import OrderedDict

def solve(k, arrivals):
    locker = OrderedDict()
    results = []
    evict_count = 0
    for pid in arrivals:
        if pid in locker:
            results.append("HIT")
            locker.move_to_end(pid)
        else:
            if len(locker) < k:
                results.append("MISS")
            else:
                locker.popitem(last=False)
                results.append("EVICT")
                evict_count += 1
            locker[pid] = True
    results.append(str(evict_count))
    return "\n".join(results)

if __name__ == "__main__":
    lines = sys.stdin.read().splitlines()
    k, n = map(int, lines[0].split())
    arrivals = list(map(int, lines[1].split())) if n > 0 else []
    print(solve(k, arrivals))

import sys
from collections import deque

def solve(lines):
    n, m = map(int, lines[0].split())
    graph = [[] for _ in range(n + 1)]
    indeg = [0] * (n + 1)
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        graph[b].append(a)
        indeg[a] += 1
    level = [0] * (n + 1)
    q = deque()
    for c in range(1, n + 1):
        if indeg[c] == 0:
            level[c] = 1
            q.append(c)
    processed = 0
    max_level = 0
    while q:
        cur = q.popleft()
        processed += 1
        max_level = max(max_level, level[cur])
        for nxt in graph[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                level[nxt] = level[cur] + 1
                q.append(nxt)
    if processed == n:
        return str(max_level)
    else:
        return "-1"

if __name__ == "__main__":
    lines = sys.stdin.read().splitlines()
    print(solve(lines))

import sys
from collections import deque

def solve(input_lines):
    n, m, k = map(int, input_lines[0].split())
    grid = []
    for i in range(1, n+1):
        grid.append(input_lines[i].strip())
    visited = [[False]*m for _ in range(n)]
    total_chips = 0
    total_clusters = 0
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '1' and not visited[i][j]:
                queue = deque([(i,j)])
                visited[i][j] = True
                cells = [(i,j)]
                while queue:
                    ci, cj = queue.popleft()
                    for di, dj in dirs:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj]=='1' and not visited[ni][nj]:
                            visited[ni][nj] = True
                            queue.append((ni,nj))
                            cells.append((ni,nj))
                if len(cells) >= k:
                    total_chips += len(cells)
                    total_clusters += 1
    return f"{total_chips} {total_clusters}"

if __name__ == "__main__":
    lines = sys.stdin.read().splitlines()
    print(solve(lines))

